def min_changes_for_semi_palindromes(s: str, k: int) -> int:
    n = len(s)
    if k <= 0 or k > n // 2:
        raise ValueError("k must satisfy 1 <= k <= n // 2")
    # Precompute palindrome edit distance for all substrings
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def pal_cost(i, j):
        # i inclusive, j inclusive
        if i >= j:
            return 0
        if s[i] == s[j]:
            if i + 1 == j:
                return 0
            return pal_cost(i + 1, j - 1)
        else:
            return 1 + min(pal_cost(i + 1, j), pal_cost(i, j - 1))
    # DP to split into k parts
    INF = float('inf')
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for length in range(1, n + 1):  # current substring length
        for m in range(1, min(k, length // 2) + 1):
            for start in range(n - length + 1):
                end = start + length - 1
                # cost of making s[start:end+1] a palindrome
                cost = pal_cost(start, end)
                if dp[start][m - 1] + cost < dp[end + 1][m]:
                    dp[end + 1][m] = dp[start][m - 1] + cost
    return dp[n][k] if dp[n][k] != INF else -1

